info-card"><div class="card-icon">♛</div><h3>SEASON REWARD</h3><p>Reach Grandmaster to earn the Celestial Sovereign recall effect.</p><button onclick="startMatch()">FIND RANKED MATCH</button></article></div>`}else{el.innerHTML=`<h1 class="sub-heading">PLAYER PROFILE</h1><div class="sub-subtitle">YOUR LEGEND, YOUR STORY</div><div class="profile-panel"><div class="profile-emblem">A</div><div><h3>ASTRALWOLF</h3><p>Level 38 · Playing since Season 02</p><div class="profile-stats"><div><b>1,284</b><small>VICTORIES</small></div><div><b>62</b><small>RANKED STARS</small></div><div><b>38</b><small>MASTERY</small></div></div></div></div>`}}
$('#inviteBtn').onclick=()=>toast('Invite sent to your online friends');$$('.invite-plus').forEach(b=>b.onclick=()=>toast('Invite sent!'));$('#modeChange').onclick=()=>{mode=mode.includes('RANKED')?'CLASSIC · 5V5':'RANKED · CLASSIC';document.querySelector('.mode-select b').textContent=mode;toast(`Mode changed to ${mode}`)};$('#playButton').onclick=startMatch;$('#menuToggle').onclick=()=>toast('Menu · Heroes · Events · Profile');
const canvas=$('#gameCanvas'),ctx=canvas.getContext('2d'),mini=$('#miniMap'),mctx=mini.getContext('2d');let raf=0,last=0,world,keys={},stick={x:0,y:0},joystickActive=false,clock=0,paused=false,matchState='';
const W=2000,H=1350,clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function unit(x,y,team,type='minion'){return{x,y,team,type,hp:type==='hero'?900:type==='tower'?1400:type==='core'?3000:260,max:type==='hero'?900:type==='tower'?1400:type==='core'?3000:260,speed:type==='hero'?180:type==='minion'?48:0,r:type==='hero'?25:type==='tower'?34:type==='core'?52:13,alive:true,cd:0,attack:0,respawn:0,level:1,phase:Math.random()*6,hit:0}}
function freshWorld(){let p=unit(190,1125,'blue','hero');p.hp=p.max=1000;p.mana=500;p.maxMana=500;p.speed=205;p.xp=0;p.gold=0;return{player:p,blue:[p,unit(410,1100,'blue','hero'),unit(390,1165,'blue','hero')],red:[unit(1760,220,'red','hero'),unit(1790,340,'red','hero'),unit(1640,260,'red','hero')],minions:[],towers:[unit(330,1025,'blue','tower'),unit(760,805,'blue','tower'),unit(1250,520,'red','tower'),unit(1670,305,'red','tower')],cores:[unit(125,1210,'blue','core'),unit(1880,130,'red','core')],effects:[],blueKills:0,redKills:0,spawnTimer:3,coreBlue:3000,coreRed:3000}}
function startMatch(){if(!$('#home').classList.contains('hidden'))$('#home').classList.add('hidden');$('#match').classList.remove('hidden');$('#matchNotice').classList.add('hidden');$('#pausePanel').classList.add('hidden');paused=false;matchState='playing';clock=0;world=freshWorld();last=performance.now();resize();if(raf)cancelAnimationFrame(raf);raf=requestAnimationFrame(loop);toast('The battle begins!')}
function resize(){const dpr=Math.min(devicePixelRatio||1,2),r=canvas.getBoundingClientRect();canvas.width=Math.max(1,Math.floor(r.width*dpr));canvas.height=Math.max(1,Math.floor(r.height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0)}window.addEventListener('resize',()=>{if(!$('#match').classList.contains('hidden'))resize()});
function addEffect(x,y,color,kind='burst'){world.effects.push({x,y,color,kind,t:0,life:kind==='beam'?.38:.55})}
