function doAttack(ultimate=false,skill=0){if(!world||paused||matchState!=='playing')return;const p=world.player;if(p.respawn>0)return;const cost=ultimate?120:skill?70:0;if(p.mana<cost){toast('Not enough mana');return}p.mana-=cost;const range=ultimate?390:skill?285:175,damage=ultimate?480:skill?190:95;let target=nearestEnemy(p.x,p.y,range);if(!target){addEffect(p.x+Math.cos(p.dir||0)*72,p.y+Math.sin(p.dir||0)*72,skill?'#8de6ff':'#f1d594','swing');if(!ultimate&&!skill)return;target=nearestEnemy(p.x,p.y,range+80)}if(!target){if(ultimate||skill)addEffect(p.x+Math.cos(p.dir||0)*150,p.y+Math.sin(p.dir||0)*150,ultimate?'#ffd66f':'#75dafa','burst');return}let hits=[target];if(skill||ultimate)hits=[...new Set([target,...[...world.red,...world.minions.filter(m=>m.team==='red'),...world.towers.filter(t=>t.team==='red'),...world.cores.filter(c=>c.team==='red')].filter(u=>u.alive&&Math.hypot(u.x-target.x,u.y-target.y)<(ultimate?165:90))])];hits.forEach((u,i)=>{u.hp-=damage;u.hit=.22;addEffect(u.x,u.y,ultimate?'#ffd56d':skill?'#69dcff':'#ffe0a2',ultimate?'burst':'beam');if(u.hp<=0){u.alive=false;if(u.type==='hero'){world.blueKills++;p.gold+=150;p.xp+=120;addFeed('LYRA','DOWN',u.team==='red'?'ENEMY');}else if(u.type==='core')finishMatch(true);else{p.gold+=u.type==='minion'?25:100;p.xp+=u.type==='minion'?30:90}}});if(skill&&p.mana<500)p.mana=Math.min(500,p.mana+12);updateUI()}
function addFeed(a,b,c){const f=document.createElement('div');f.className='feed-item';f.textContent=`${a}  ⚔  ${b} ${c}`;$('#killFeed').prepend(f);while($('#killFeed').children.length>3)$('#killFeed').lastChild.remove();setTimeout(()=>f.remove(),5000)}
function updateUI(){if(!world)return;const p=world.player;$('#blueKills').textContent=world.blueKills;$('#redKills').textContent=world.redKills;$('#heroLevel').textContent=p.level;$('#levelBadge').textContent=p.level;$('#hpBar').style.width=`${100*p.hp/p.max}%`;$('#manaBar').style.width=`${100*p.mana/p.maxMana}%`;$('#xpBar').style.width=`${p.xp%300/3}%`;$('#hpText').textContent=`${Math.ceil(p.hp)} / ${p.max}`;$('#manaText').textContent=`${Math.ceil(p.mana)} / ${p.maxMana}`}
