function tick(dt){if(!world||paused||matchState!=='playing')return;clock+=dt;$('#matchClock').textContent=`${String(Math.floor(clock/60)).padStart(2,'0')}:${String(Math.floor(clock%60)).padStart(2,'0')}`;const p=world.player;world.spawnTimer-=dt;if(world.spawnTimer<=0){world.spawnTimer=11;for(let i=0;i<3;i++){world.minions.push(unit(215+i*17,1100+i*25,'blue'));world.minions.push(unit(1785-i*17,230+i*23,'red'))}}
