if(p.attack<=0){let t=nearestEnemy(p.x,p.y,150);if(t){t.hp-=36;t.hit=.15;p.attack=.95;addEffect(t.x,t.y,'#f3d996','swing');if(t.hp<=0){t.alive=false;p.gold+=25;p.xp+=25}}}
