for(const e of world.effects)e.t+=dt;world.effects=world.effects.filter(e=>e.t<e.life);world.minions=world.minions.filter(m=>m.alive||m.hp>0);if(p.xp>=300*p.level){p.xp-=300*p.level;p.level++;p.max+=100;p.maxMana+=30;p.hp=p.max;p.mana=p.maxMana;toast(`LEVEL UP · LEVEL ${p.level}`)}updateUI();drawMini()}
